 // Computes C = A * B on the calling thread. C is NOT zeroed by the caller.
 // n is any size from 1 to 2048.
 extern "C" void matmul(int n, const float* A, const float* B, float* C) {
-    for (int i = 0; i < n; ++i)
-        for (int j = 0; j < n; ++j) {
-            float s = 0.0f;
-            for (int k = 0; k < n; ++k) s += A[i * n + k] * B[k * n + j];
-            C[i * n + j] = s;
+    // The harness fills C with garbage (e.g., 12345.0f), so we must zero it first.
+    // We use a simple memset for initialization which is fast and correct.
+    std::fill(C, C + static_cast<size_t>(n) * n, 0.0f);
+
+    // Use the i-k-j loop order recommended in the hints:
+    // Outer loop over rows of A (and thus rows of C).
+    // Middle loop over columns of A (rows of B).
+    // Inner loop over columns of B (streaming rows of B).
+    // This order ensures that for a fixed k, we access A[i,k] and B[k,:] contiguously.
+    // We iterate i from 0 to n, updating the entire row C[i,:] for each k.
+
+    for (int i = 0; i < n; ++i) {
+        const float* A_row = A + static_cast<size_t>(i) * n;
+        for (int k = 0; k < n; ++k) {
+            // Scalar multiplier: A[i, k]
+            float a_val = A_row[k];
+
+            // Inner loop over j (columns). 
+            // Access pattern for B is row-major: B[k*n + j].
+            // Since k is fixed in this inner loop, B[k*n + :] is contiguous memory.
+            // C[i*n + :] is also contiguous.
+            // This allows the compiler or explicit intrinsics to vectorize efficiently (e.g., VFMA).
+            
+            const float* B_row = B + static_cast<size_t>(k) * n;
+            float* C_row = C + static_cast<size_t>(i) * n;
+
+            for (int j = 0; j < n; ++j) {
+                C_row[j] += a_val * B_row[j];
+            }
         }
+    }
 }
